<?php
namespace Core\Pan;require_once __DIR__.'/../Guard.php';ml_guard_shield(__FILE__);class Transfer{public static function transfer($pan,$url,$title=''){$fail=function($a){return array('ok'=>false,'new_url'=>'','share_id'=>'','error'=>(string)$a);};self::needPanTransfer();$pans=\Core\PanTransfer::pans();if(!isset($pans[$pan])){return $fail('暂不支持自动转存该网盘');}$cfg=$pans[$pan];$class=isset($cfg['adapter'])?(string)$cfg['adapter']:'';if($class===''||!preg_match('/^[A-Z][A-Za-z0-9]*$/',$class)){return $fail('该网盘未装配转存适配器');}$full='Core\\Pan\\'.$class;if(!class_exists($full,false)){$file=__DIR__.'/'.$class.'.php';if(!is_file($file)){return $fail('转存适配器缺失：'.$class);}require_once $file;}if(!class_exists($full,false)){return $fail('转存适配器无法加载：'.$class);}$shareId=\Core\PanTransfer::shareId($pan,$url);if($shareId===''&&empty($cfg['own'])){return $fail('无法从链接中识别分享 ID');}$adapter=new $full(array('code'=>$pan,'title'=>(string)$title,'passcode'=>\Core\PanTransfer::passcode($url),'url'=>$url,'isType'=>0,'expired_type'=>1,'ad_fid'=>'','stoken'=>'','cfg'=>$cfg,));try{$res=$adapter->transfer($shareId);}catch(\Throwable $e){return $fail($e->getMessage());}return self::normalize($pan,$res);}private static function normalize($a,$b){$c=array('ok'=>false,'new_url'=>'','share_id'=>'','error'=>'');if(!is_array($b)||!isset($b['code'])){$c['error']='适配器返回异常';return $c;}if((int)$b['code']!==200){$c['error']=isset($b['message'])?(string)$b['message']:'转存失败';return $c;}$d=isset($b['data'])&&is_array($b['data'])?$b['data']:array();$e=isset($d['share_url'])?trim((string)$d['share_url']):'';if($e===''){$c['error']='适配器未返回分享地址';return $c;}$c['ok']=true;$c['new_url']=$e;$f=isset($d['share_id'])?trim((string)$d['share_id']):'';if($f===''){$f=\Core\PanTransfer::shareId($a,$e);}$c['share_id']=$f;return $c;}public static function listFiles($pan,$pdir_fid='0'){$fail=function($a){return array('ok'=>false,'list'=>array(),'error'=>(string)$a);};self::needPanTransfer();$pans=\Core\PanTransfer::pans();if(!isset($pans[$pan])){return $fail('未知的网盘类型');}if(!empty($pans[$pan]['own'])){return $fail('磁力链接没有目录可选');}$cfg=$pans[$pan];$class=isset($cfg['adapter'])?(string)$cfg['adapter']:'';if($class===''||!preg_match('/^[A-Z][A-Za-z0-9]*$/',$class)){return $fail('该网盘不支持浏览目录');}$full='Core\\Pan\\'.$class;if(!class_exists($full,false)){$file=__DIR__.'/'.$class.'.php';if(!is_file($file)){return $fail('目录适配器缺失：'.$class);}require_once $file;}if(!class_exists($full,false)){return $fail('目录适配器无法加载：'.$class);}$adapter=new $full(array('code'=>$pan,'cfg'=>$cfg,));try{$res=$adapter->getFiles($pdir_fid);}catch(\Throwable $e){return $fail('获取目录失败：'.$e->getMessage());}if(!is_array($res)||!isset($res['code'])){return $fail('适配器返回异常');}if((int)$res['code']!==200){$msg=isset($res['message'])?trim((string)$res['message']):'';return $fail($msg!==''?$msg:'获取目录失败');}$list=isset($res['data'])&&is_array($res['data'])?$res['data']:array();return array('ok'=>true,'list'=>$list,'error'=>'');}private static function needPanTransfer(){if(!class_exists('Core\\PanTransfer',false)){$f=__DIR__.'/../PanTransfer.php';if(is_file($f)){require_once $f;}}}}